-- Gerado por ferramentas/docx_para_sql.py — etapa 2, parte 5 de 8
-- Pode ser executado mais de uma vez; as partes podem ser executadas em qualquer ordem.
begin;
do $$ begin if (select count(*) from encontros where etapa_id=(select id from etapas where numero=2)) <> 35 then raise exception 'A etapa 2 não tem 35 encontros no banco — a atualização por ordem não é segura.'; end if; end $$;
update encontros set conteudo_html='<p><strong>Palavra inicial:</strong> Neste encontro queremos ressaltar o grande Amor que Deus tem por cada um de nós. É um amor incondicional, capaz de entregar o seu próprio Filho para resgatar-nos do pecado. Queremos refletir, além disso, que é esse amor que devemos anunciar a tantas pessoas que não se sentem amadas e com amor acolhê-las em nosso meio.</p> <p><strong>Preparar o ambiente:</strong> Ambão com toalha da cor do Tempo Litúrgico, vela, flores. Para a dinâmica: Papel pardo ou folha de jornal (01 para cada catequizando), aparelho de som e música alegre/descontraída.</p> <p><strong>Acolhida:</strong> O catequista acolhe os catequizandos, saudando-os e conduzindo-os ao interior da sala: "...N... nosso Deus é amor. Seja bem-vindo!"</p> <p><strong>Recordação da vida:</strong> Ao redor da Mesa da Partilha ou da Mesa da Palavra os catequizandos farão uma retrospectiva da semana, e o catequista poderá perguntar sobre o encontro anterior, pedindo que partilhem o que cada um experimentou. Poderão destacar, além disso, os acontecimentos importantes que possam ter ocorrido na vida da comunidade.</p> <h4>Na Mesa da Palavra</h4> <p><strong>Oração inicial:</strong> Colocando no coração de Deus todos os elementos trazidos durante a recordação da vida, o catequista inicia a oração invocando o Espírito Santo e pedindo que Deus derrame o seu amor no coração de cada catequizando. Todos poderão aclamar o Evangelho e o catequizando (designado como leitor do encontro) dirige-se até o ambão, de onde proclama o texto bíblico.</p> <p><strong>Leitura do texto bíblico:</strong> Jo 3,16-21. Depois de um momento de silêncio o catequista lê o texto novamente bem devagar, destacando alguns pontos.</p> <p>"Deus amou tanto o mundo que entregou o seu Filho único, para que todo aquele que nele crer não morra, mas tenha a vida eterna..."</p> <p>Todos se dirigem à Mesa da Partilha.</p> <h4>Na Mesa da Partilha</h4> <p>Deixar que os catequizandos falem do que cada um entendeu sobre o texto. Depois pedir aos catequizandos que abram suas bíblias na passagem proclamada na Mesa da Palavra, e convidá-los a uma leitura silenciosa, observando algum detalhe não comentado na reconstrução do texto. Depois refletir junto a eles, enfatizando o grande amor que Deus tem por cada um de nós. Logo após, o catequista poderá contar a história "Feliz Natal".</p> <p>Feliz Natal!</p> <p>E chegou a hora tão esperada pelas crianças: a hora da representação do Auto de Natal. Tudo foi muito bonito e tudo havia dado certo. Zezinho teve a ajuda de Wilson para se ajoelhar na hora de entregar os presentes dos reis magos ao Menino Jesus e não caiu sobre ele. A última frase do teatro era de Leandro, que interpretava o Arcanjo Gabriel. Diante de Isabel e Otávio, que interpretavam Maria e José, disse a toda a assembleia reunida na igreja matriz:</p> <p>– E Deus veio pisar nesta terra criada por Ele. Fez-se homem para morrer por amor de suas criaturas. E nasceu pobre para que todos aprendessem com Ele que a maior riqueza está no coração, que é o que podemos fazer de bom pelos nossos irmãos sem esperar nada em troca. Feliz Natal!</p> <p>Depois um coro de anjos cantou a música "Noite Feliz", emocionando ainda mais as pessoas.</p> <p><strong>Dinâmica:</strong> Depois da história o catequista deverá entregar uma folha (papel pardo ou folha de jornal) a cada catequizando. Deverá explicar que esse papel representa uma ilha. E que cada catequizando deverá manter-se na sua ilha, pois ao redor há muita água com tubarões (imaginários). Os catequizandos recebem o papel e ficam em pé sobre ele. O catequista diz que esses tubarões de vez em quando dormem. E quando isso ocorre os catequizandos poderão passear de uma ilha a outra. O catequista então explica que colocará uma música, e essa música indica que os tubarões estão dormindo. Ao parar a música, todos devem correr para alguma ilha (representada pelo papel), para não serem mordidos por um tubarão.</p> <p>O catequista inicia a dinâmica, colocando a música. Enquanto a música toca, os catequizandos poderão deslocar-se. O que ocorrerá é que o catequista, antes de desligar a música, sempre recolherá algumas dessas folhas. Dessa forma, o catequizando que ficar sem a sua ilha deverá procurar refúgio em outra ilha, junto com outro catequizando. Isto ocorrerá várias vezes, até que sobre apenas uma folha, obrigando todos os catequizandos a estarem unidos nessa mesma folha (ilha). Os catequizandos deverão acolher os seus companheiros e não os deixar à mercê do tubarão.</p> <p>Depois da dinâmica refletir sobre a unidade e solidariedade que o cristão necessita exercitar com todos, sem excluir as pessoas. O catequista poderá fazer uma analogia desta dinâmica com o amor de Deus por todos nós. Ele nos quer sempre unidos. Nos ama tanto que não quer que ninguém se perca. A água do mar representa o mundo, os tubarões nossas dificuldades, tentações, erros (que querem nos engolir). A ilha é o próprio Deus, que é fonte segura que nos quer sempre unidos, acolhendo a todos e não querendo que ninguém se perca.</p> <p>Muitas vezes nos distanciamos dessa ilha (Deus) por causa do pecado, das coisas que desagradam a Deus. Mas Ele sempre está presente. O seu amor é tão grande que abriga a todos os que o buscam. Deus, para não deixar que ninguém se perdesse, que ninguém morresse, entregou à morte o seu próprio Filho por amor a nós, para nos salvar. Será que nós teríamos essa disposição de dar o nosso lugar na...</p> <p>...ilha e morrer para salvar o nosso irmão? Deus morreu por nós e a seu exemplo temos que doar a nossa vida por nosso próximo. Só o amor mudará as situações de injustiça e os ambientes sem esperança.</p> <p><strong>Conclusão:</strong> O catequista poderá além disso citar vários exemplos do Amor de Deus para conosco: a criação do mundo, a vinda do seu Filho, os seus "sinais" (milagres) e a esperança que está conosco até o fim dos tempos (os catequizandos poderão ser motivados a citar alguns exemplos do amor de Deus para conosco). O que ocorre é que muitas vezes não entendemos esse amor, pois não estamos acostumados a um amor incondicional (sem troca). Mas esse Amor (muitas vezes já provado) existe e vem de Deus. O compromisso da semana será falar desse amor de Deus a alguém. Pode ser alguém da nossa família, ou um coleguinha. Não basta apenas ter ciência do Amor de Deus, é preciso senti-lo e transmiti-lo a outras pessoas.</p> <p><strong>Oração final:</strong> O catequista convida a todos a se colocarem ao redor da Mesa da Palavra de onde estimula os catequizandos a louvarem a Deus por suas obras de amor, citando fatos, coisas e acontecimentos do nosso dia a dia. Ao final reza o Pai-nosso e conclui com a oração:</p> <p>Senhor, em um mundo que muitas vezes desconhece o teu amor, ajuda-nos no compromisso de transmiti-lo a outras pessoas, de proclamá-lo a todos os que nos rodeiam, e dessa forma aumentar ainda mais o número de pessoas que possam provar e sentir todas as tuas promessas de Boa Nova. Ajuda-nos! Por Cristo Nosso Senhor. Amém!</p> <p>Ao final da oração, o catequista impõe as mãos sobre a cabeça de cada catequizando e traça o sinal da cruz em sua fronte, dizendo: "...N... nasceste para o amor. Vai em paz, e que o Senhor te acompanhe! Amém".</p>', preparo_html='<p>Ambão com toalha da cor do Tempo Litúrgico, vela, flores. Para a dinâmica: Papel pardo ou folha de jornal (01 para cada catequizando), aparelho de som e música alegre/descontraída.</p>', atualizado_em=now() where etapa_id=(select id from etapas where numero=2) and ordem=24; -- Um Deus de amor
update encontros set conteudo_html='<p><strong>Palavra inicial:</strong> Com este encontro queremos refletir com os catequizandos que o Espírito Santo, terceira pessoa da Santíssima Trindade, é aquele que nos auxilia, que nos santifica, que nos dá a coragem e o impulso de servir a Deus e testemunhar a Verdade de Cristo.</p> <p><strong>Preparar o ambiente:</strong> Ambão com toalha da cor do Tempo Litúrgico, flores e símbolos que representam o Espírito Santo: água, fogo, óleo do crisma, pomba. Para a dinâmica, espalhar velas pela sala de encontro e providenciar pedaços de pano ou TNT para que os catequizandos se deitem no chão, aparelho de som e música de relaxamento ou instrumental.</p> <p><strong>Acolhida:</strong> O catequista acolhe os catequizandos, saudando-os carinhosamente: "Seja bem-vindo... N..., templo vivo do Espírito Santo!" Quando todos estiverem na sala, saúda a todos mais uma vez, desejando-lhes boas-vindas.</p> <p><strong>Recordação da vida:</strong> Depois de serem acolhidos, convida-os a colocarem-se ao redor da Mesa da Partilha ou da Mesa da Palavra, onde farão uma retrospectiva da semana, e o catequista poderá recordar o encontro anterior, pedindo que partilhem o que cada um experimentou. Poderão destacar, além disso, os acontecimentos importantes que possam ter ocorrido na vida da comunidade.</p> <h4>Na Mesa da Palavra</h4> <p><strong>Oração inicial:</strong> O catequista motiva um momento de oração, criando um clima de interiorização para o início do encontro e para a proclamação da Palavra. Antes, porém, todos poderão aclamar o Evangelho com um canto. O catequizando (designado como leitor do encontro) se dirige até o ambão, de onde proclama o texto bíblico.</p> <p><strong>Leitura do texto bíblico:</strong> Jo 14,25-27. Depois de um momento de silêncio o catequista lê o texto novamente bem devagar, destacando alguns pontos.</p> <p>"[...] o Espírito Santo que o Pai enviará em meu nome, Ele vos ensinará tudo e vos recordará tudo o que vos disse. Deixo-vos a paz..."</p> <p>Todos se dirigem à Mesa da Partilha.</p> <h4>Na Mesa da Partilha</h4> <p>O catequista pede aos catequizandos que falem sobre o que entenderam da passagem bíblica deste encontro. Deixar que falem. Depois pedir aos catequizandos que abram suas bíblias na passagem proclamada na Mesa da Palavra, e convidá-los a uma leitura silenciosa observando algum detalhe não comentado na reconstrução do texto. Se houver algo, todos podem partilhar. Depois o catequista pergunta aos catequizandos se já sentiram a presença do Espírito Santo. Se em algum momento de medo, de dificuldade, sentiram uma calma e uma paz, uma força que os ajudava. Deixar que falem.</p> <p>O catequista poderá depois, na medida do possível, valorizar o que cada catequizando disse e pedir que se imaginem no topo de uma montanha, onde sentem uma brisa leve e o vento bater no seu rosto. Depois diz que esse vento não pode ser visto pelos nossos olhos, mas pode ser sentido. E completa dizendo que assim é o Espírito Santo, não podemos vê-lo, mas o sentimos a todo instante na nossa vida. O catequista além disso poderá convidá-los a fazer essa experiência de sentir e clamar ao Espírito Santo nas suas vidas como na dinâmica seguinte.</p> <p><strong>Dinâmica:</strong> Pedir que cada catequizando pegue um pedaço de tecido ou TNT e se deite no chão, espalhando-se pela sala de encontro. Depois o catequista acende as velas espalhadas pela sala e, se possível, diminui a claridade da mesma, fechando as cortinas ou apagando as luzes. Convida-os por um momento a clamar ao Espírito Santo, rezando e cantando uma música de invocação do Espírito Santo. Depois coloca de fundo uma música instrumental ou de relaxamento e com um tom de voz baixo, o catequista pede aos catequizandos que sintam a paz que só Deus pode dar. O catequista poderá conduzir um momento de oração, pedindo que se concentrem e deixem de lado todas as distrações, e vai pedindo que Deus possa enviar o Santo Espírito sobre eles, para curá-los, santificá-los e fortalecê-los na fé. Ficar um período em silêncio, deixando apenas a música de fundo.</p> <p><strong>Conclusão:</strong> O catequista, após um tempo oportuno, pede que todos se assentem onde estão e partilhem o que cada um sentiu.</p> <p><strong>Oração final:</strong> O catequista convida a todos a se colocarem ao redor da Mesa da Palavra onde estimula os catequizandos a louvarem e agradecerem por todas as experiências e sentimentos vivenciados. Podem formular preces pelas suas vidas e pelas suas famílias. Conclui com o Pai-nosso e com a oração:</p> <p>Deus nosso Pai, que enviastes o Espírito Santo santificador sobre cada um de nós. Fortalecei-nos na missão e no seguimento de vossa Palavra, fazendo-nos templos vivos de amor para todos os que nos forem confiados. Por Cristo Nosso Senhor. Amém.</p> <p>Ao final da oração, o catequista impõe as mãos sobre a cabeça de cada catequizando e traça o sinal da cruz em sua fronte, dizendo: "...N... o Senhor está contigo, vai em paz!"</p> <h4>Material de apoio</h4> <ul> <li><p>Aprofundar o tema nos parágrafos 683 a 747 do Catecismo da Igreja Católica (CIC);</p></li> <li><p>No Símbolo niceno-constantinopolitano: "[...] Creio no Espírito Santo, Senhor que dá a vida e procede do Pai e do Filho; e com o Pai e o Filho é adorado e glorificado: Ele que falou pelos profetas...".</p></li> </ul>', preparo_html='<p>Ambão com toalha da cor do Tempo Litúrgico, flores e símbolos que representam o Espírito Santo: água, fogo, óleo do crisma, pomba. Para a dinâmica, espalhar velas pela sala de encontro e providenciar pedaços de pano ou TNT para que os catequizandos se deitem no chão, aparelho de som e música de relaxamento ou instrumental.</p>', atualizado_em=now() where etapa_id=(select id from etapas where numero=2) and ordem=25; -- Creio no Espírito Santo
update encontros set conteudo_html='<p><strong>Palavra inicial:</strong> Querido catequista, hoje refletiremos sobre o 9º artigo da Profissão de Fé. Queremos apresentar a Igreja não como um espaço físico, mas como povo de Deus, grupo de batizados reunidos na mesma fé em Cristo Jesus.</p> <p><strong>Preparar o ambiente:</strong> Ambão com toalha da cor do Tempo Litúrgico, vela, flores e imagem ou quadro de São Pedro.</p> <p><strong>Acolhida:</strong> À medida que os catequizandos vão chegando, o catequista os acolhe, saudando-os com a frase: "Formamos um só corpo... N..., seja bem-vindo!", e convidando-os a entrar no local do encontro.</p> <p><strong>Recordação da vida:</strong> Ao redor da Mesa da Partilha ou da Mesa da Palavra o catequista motiva os catequizandos a fazerem um momento de recordação da vida, onde recordarão fatos e acontecimentos que marcaram a vida de cada um, de suas famílias, comunidade e da sociedade.</p> <h4>Na Mesa da Palavra</h4> <p><strong>Oração inicial:</strong> Depois do momento de recordação da vida, o catequista inicia um momento de oração pedindo o Espírito Santo sobre todos os catequizandos e sobre toda a Igreja. Poderá rezar o Credo. Em espírito de oração todos aclamam o Evangelho com um canto e o catequizando (designado como leitor do encontro) se dirige até o ambão, de onde proclama o texto bíblico.</p> <p><strong>Leitura do texto bíblico:</strong> Mt 16,13-19. Depois de um momento de silêncio o catequista lê o texto novamente bem devagar, destacando alguns pontos.</p> <p>"[...] E eu te declaro: Tu és Pedro e sobre esta pedra construirei a minha Igreja..."</p> <p>Todos se dirigem à Mesa da Partilha.</p> <h4>Na Mesa da Partilha</h4> <p>O catequista incentiva os catequizandos a reconstruírem o texto bíblico. Depois pedir aos catequizandos que abram suas bíblias na passagem proclamada na Mesa da Palavra, e convidá-los a uma leitura silenciosa, observando algum detalhe não comentado na reconstrução do texto. Se houver algo, todos podem partilhar. Logo após conta a história "Quem é o Papa mesmo?", sublinhando que a Igreja é um projeto de Deus e que Pedro foi escolhido para ser o primeiro papa da Igreja.</p> <p>Quem é o papa mesmo?</p> <p>Muitos dias haviam se passado. A nossa amiguinha Isabel e os gêmeos Otávio e Leandro participaram da missa em que se celebrou o dia dos apóstolos São Pedro e São Paulo. Depois da missa almoçaram na casa paroquial a convite do Padre Pedro, que comemorava seu aniversário, junto com os pais. E aí Otávio disse que foi muito legal ter conhecido São Pedro durante a viagem no tempo e que teria gostado de ter conhecido também a Paulo. E conversando sobre a Igreja, a religião Católica Apostólica Romana, as três crianças ficaram sabendo que Pedro tinha sido escolhido por Jesus para ser o primeiro papa. E o papa é quem mesmo? Sabe dizer?</p> <p>Ao final da historinha perguntar aos catequizandos o que sabem sobre a "Igreja". Deixar que falem livremente. Depois explicar aos catequizandos que a palavra "igreja" significa "convocação". É todo o povo que Deus convoca e reúne para constituir o seu Corpo. São todos os que, pela fé e pelo Batismo, se tornam filhos e filhas de Deus. A Igreja não é o local, a Igreja somos todos nós, assembleia, fiéis, batizados que se reúnem em torno da mesma fé em Cristo Senhor (Igreja com "I" maiúsculo). A igreja templo (pedra) é o lugar do encontro da Igreja povo com o seu Deus (igreja com "i" minúsculo; diferença até na escrita). Diante do caos do mundo, da violência, o ser humano necessita de lugares para reunir-se em assembleia. Mas a Igreja é muito mais do que um simples templo, a Igreja somos todos nós batizados, brancos e negros, índios e mestiços. São os que cantam e os que pintam, são os que limpam e os que leem, é a diversidade de dons que cada um coloca a serviço da comunidade.</p> <p>A Igreja é santa, pois foi o próprio Deus quem a constituiu, a criou e por ela Jesus Cristo se entregou, para santificá-la e torná-la santificante, e o Espírito Santo a vivifica com a caridade. Mas também é pecadora, por ser formada por homens pecadores, frágeis e limitados. É católica, isto é, universal, porque nela está presente Cristo. Ela anuncia a totalidade e a integridade da fé e é enviada em missão a qualquer tempo e a qualquer cultura.</p> <p>"Ide por todo o mundo e anunciai o Evangelho a toda a humanidade" (Mc 16,15).</p> <p>Mostrando a imagem de São Pedro, o catequista explica aos catequizandos que Pedro foi o escolhido para ser o primeiro papa da Igreja, foi o escolhido para ser o primeiro "chefe", aquele que seria a pedra, o alicerce do futuro organizacional da Igreja. O catequista poderá apresentar a lista de todos os papas que vieram depois de Pedro, mostrando a sucessão ininterrupta de pastores. O catequista além disso poderá refletir sobre o Sacramento do Batismo, como porta de entrada para ser membro da Igreja. Sendo batizados passamos a pertencer a essa grande família que é a Igreja Católica Apostólica Romana. No batismo recebemos um sobrenome comum: "cristão" e por isso somos todos chamados irmãos. Formamos um grande CORPO, cuja cabeça é Cristo. Nesta grande família cada um tem uma função, assim como o nosso corpo. O catequista poderá pedir que os catequizandos observem seu próprio corpo (mãos, olhos, pés...) e o comparem com a Igreja, onde cada pessoa coloca o seu dom a serviço da comunidade. Na Igreja ninguém pode viver isolado, todos dependemos uns dos outros.</p> <p><strong>Conclusão:</strong> O catequista poderá perguntar se sabem o dia em que foram batizados. Se não souberem, pedir que durante a semana façam uma pesquisa para descobrir a data. Aos catequizandos que ainda não foram batizados, o catequista poderá sublinhar que receberão o batismo na quarta etapa da catequese, onde será um momento muito especial e importante para toda a Igreja.</p> <p><strong>Oração final:</strong> O catequista convida a todos a se colocarem ao redor da Mesa da Palavra, onde estimula os catequizandos a formularem preces e orações pela Igreja do mundo inteiro, principalmente pelos missionários e missionárias que dedicam toda a sua vida ao anúncio do Evangelho. Conclui com o Pai-nosso e com a oração:</p> <p>Deus nosso Pai, Vós que nos criastes e nos formastes para viver como uma só família em vossa Igreja, pedimos que sejamos fiéis na missão de testemunhar-vos e anunciar-vos a todos os povos. Por Cristo Nosso Senhor. Amém.</p> <p>Nossa família é feita de todas as raças. Nós somos jovens e velhos, ricos e pobres, homens e mulheres, pecadores e santos. Nossa família se difundiu pelos séculos e pelo mundo. Com a graça de Deus, nós abrimos hospitais para cuidar dos doentes, fundamos orfanatos e ajudamos os pobres. Nós somos a maior organização caritativa no planeta, trazemos alívio e conforto àqueles que precisam. Nós educamos mais crianças do que qualquer outra instituição educativa ou religiosa. Nós desenvolvemos o método científico e as leis de evidência. Nós fundamos o sistema universitário. Nós defendemos a dignidade de toda a vida humana e preservamos o casamento e a família. Cidades receberam os nomes de nossos venerados santos, que percorreram o caminho da santidade antes de nós. Guiados pelo Espírito Santo, nós compilamos a Bíblia. Nós somos transformados pela Sagrada Escritura e pela Sagrada Tradição, que nos têm guiado firmemente por dois mil anos. Nós somos a Igreja Católica. Com mais de um bilhão na nossa família compartilhando dos sacramentos e da plenitude da fé cristã. Por séculos, temos rezado por todo o mundo, a cada hora, a cada dia, sempre que celebramos a missa. O próprio Jesus lançou os fundamentos de nossa fé quando disse a Pedro, o primeiro papa: <em>"Tu és Pedro, e sobre esta pedra edificarei a minha Igreja"</em>. Por mais de dois mil anos tivemos uma linha ininterrupta de pastores guiando a Igreja Católica com amor e verdade, num mundo confuso e doloroso de se viver. E nesse mundo cheio de caos, dificuldades e dor, é reconfortante saber que algumas coisas permanecem coerentes, verdadeiras e fortes: nossa fé católica e o eterno amor que Deus tem por toda a criação.</p> <p>Sugestão</p> <p>No site do YouTube na internet, o catequista encontrará o vídeo com o <em>"Comercial da Igreja Católica nos EUA"</em> (Católicos voltam para casa – Narrado em português) de quase três minutos, o qual poderá passar aos catequizandos para que tenham uma visão mais ampla da Igreja. Segue o texto narrado no comercial:</p> <h4>Material de apoio</h4> <ul> <li><p>Aprofundar o tema nos parágrafos 748 a 945 do Catecismo da Igreja Católica (CIC).</p></li> <li><p>No Símbolo niceno-constantinopolitano: <em>"[...] Creio na Igreja, una, santa, católica e apostólica..."</em></p></li> </ul> <p><em>"...N..., amai a vossa Igreja, ide em paz, e que o Senhor te acompanhe!"</em></p> <p>No final da oração, o catequista impõe as mãos sobre a cabeça de cada catequizando e traça o sinal da cruz em sua fronte, dizendo:</p>', preparo_html='<p>Ambão com toalha da cor do Tempo Litúrgico, vela, flores e imagem ou quadro de São Pedro.</p>', atualizado_em=now() where etapa_id=(select id from etapas where numero=2) and ordem=26; -- Creio "na Santa Igreja Católica"
update encontros set conteudo_html='<p><strong>Palavra inicial:</strong> Amados catequistas, neste encontro queremos refletir sobre a organização e a estrutura da Igreja Católica Apostólica Romana (papa, clero, dioceses, paróquias...).</p> <p><strong>Preparar o ambiente:</strong> Ambão com toalha da cor do Tempo Litúrgico, vela e flores, mapa territorial da diocese e foto do bispo diocesano, do pároco e vigários paroquiais, se houver.</p> <p><strong>Acolhida:</strong> O catequista acolhe os catequizandos, saudando-os e conduzindo-os para dentro da sala: <em>"Seja bem-vindo ...N..., ramo da grande videira do Senhor"</em>. Quando já estiverem na sala, saúda a todos mais uma vez, desejando-lhes boas-vindas.</p> <p><strong>Recordação da vida:</strong> Ao redor da Mesa da Partilha ou da Mesa da Palavra, o catequista motiva os catequizandos a fazerem um momento de recordação da vida, destacando fatos e acontecimentos que marcaram a vida da comunidade. Poderá também recordar o encontro passado, perguntando aos catequizandos se descobriram o dia em que foram batizados.</p> <h4>Na Mesa da Palavra</h4> <p><strong>Oração inicial:</strong> Após a recordação da vida o catequista inicia a oração, de maneira bem espontânea, invocando o Espírito Santo, onde também poderá ser rezado o Credo. O catequista convida a todos a aclamarem o Evangelho com um canto.</p> <p>O catequizando (escalado como leitor do encontro) dirige-se até o ambão, de onde proclama o texto bíblico. Antes, porém, todos poderão cantar, aclamando o Santo Evangelho.</p> <p><strong>Leitura do texto bíblico:</strong> <em>Jo 15,1-6</em>.</p> <p>Depois de um momento de silêncio o catequista lê o texto novamente bem devagar, destacando alguns pontos:</p> <p><em>"[...] Eu sou a videira, vós os ramos. Quem permanece em mim, e eu nele, dá muito fruto..."</em></p> <p>Todos se dirigem para a Mesa da Partilha.</p> <h4>Na Mesa da Partilha</h4> <p>Os catequizandos reconstroem o texto bíblico. Deixar que falem. Depois pedir aos catequizandos para abrirem suas bíblias na passagem proclamada na Mesa da Palavra, e os convida a uma leitura silenciosa, observando algum detalhe não comentado na reconstrução do texto. Se houver algo, todos podem partilhar. Logo após, o catequista conta a história "Rezando com Jesus", frisando que a Igreja é uma grande família onde cada um tem um papel e uma função, ninguém é maior ou melhor que ninguém, somos todos iguais e estamos todos a serviço.</p> <p>Rezando com Jesus</p> <p>Ainda conversando sobre a Igreja Católica e qual é a função do papa, nossos amiguinhos se lembraram dos dias que passaram acompanhando os discípulos em algumas missões, anunciando o Evangelho.</p> <p>– E mesmo crianças, vocês são chamados a serem pequenos discípulos missionários de Jesus. Com certeza não viajaram no tempo à toa.</p> <p>– Nós fizemos a mesma viagem e descobrimos que éramos chamados a evangelizar outras crianças, ou seja, falar de Jesus, do Reino de Deus a elas.</p> <p>– Ah mãe, a gente sabe disso, a gente conversou sobre isso quando estávamos no passado. A gente só não sabe por onde começar.</p> <p>– Pois comece falando com seus primos, colegas da escola, do inglês, do futebol, os vizinhos. Quando vocês estão com eles, falam de Jesus? Conversam sobre o que deve ser feito para que o nosso mundo seja melhor?</p> <p>– Nem sempre, pai – respondeu Leandro.</p> <p>– Todos os católicos devem lembrar que somos Igreja em todos os ambientes que estamos, não só quando estamos na missa ou participando de algum evento ou reunião dela.</p> <p>– E como que a gente começa um assunto assim? – quis saber Isabel.</p> <p>– Não precisa ficar ensaiando, Isabel. É só deixar que o Espírito Santo de Deus aja e fale por meio de vocês. Por isso, é importante sempre rezarem, e não rezarem as orações que todo católico decoram, mas conversar mesmo com Jesus, como um amigo – respondeu o padre.</p> <p>– Vocês podem rezar pedindo que Jesus as ajudem a encontrar esses momentos certos de falar sobre Ele, sobre tudo o que Ele veio ensinar para que o mundo fosse melhor e mais gostoso para viver, como se aqui já fosse o céu – esclareceu Fernando.</p> <p>As crianças ficaram pensativas, e com certeza, antes de dormir rezariam não só a oração do Pai-nosso, Ave-Maria ou do Santo Anjo, mas também conversariam com Jesus, agradecendo pelo dia que tiveram, pedindo bênçãos sobre seus pais, amigos e familiares. E você, como tem rezado? Como você conversa com Jesus? O que você vai dizer hoje a Ele antes de dormir?</p> <p>Após a história o catequista deverá refletir com os catequizandos se eles conhecem a estrutura e organização da Igreja, mostrando a importância da mesma. O símbolo da videira poderá ilustrar a Igreja onde Cristo é tronco e a Igreja seus ramos.</p> <p>Pequeno esquema para nortear a explicação:</p> <ul> <li><p>Igreja Universal: Sede em Roma, conduzida pelo Papa ...N...</p></li> <li><p>Conferências episcopais: responsáveis por articular as dioceses no país. No Brasil temos a "Conferência Nacional dos Bispos do Brasil" (CNBB).</p></li> <li><p>Regionais: Divididos por estados, formam os regionais, responsáveis por articular as ações da Igreja em determinada região. No Brasil temos 17 regionais (ver material de apoio).</p></li> <li><p>Diocese ou arquidiocese: Também chamado de "Igreja particular" a diocese ou arquidiocese é formada por várias paróquias que têm como pastor o bispo ou arcebispo (aqui o catequista poderá apresentar o mapa da sua diocese, bem como a foto do bispo ou arcebispo, explorando, se preferir, um pouco da história da mesma).</p></li> </ul> <p>Lembramos que a diferença de diocese e da arquidiocese é que a arquidiocese é a sede da província, que é formada por várias dioceses. Exemplo: A diocese de Barretos pertence à Província Eclesiástica de Ribeirão Preto, que é formada por oito dioceses (Ribeirão Preto, Jaboticabal, Franca, São João da Boa Vista, Barretos, São José do Rio Preto, Catanduva e Jales), sendo assim, Ribeirão Preto é chamada de arquidiocese por ser a sede da província que congrega as oito dioceses.</p> <ul> <li><p>Paróquias: É formado por um determinado território onde existe um padre (pároco) responsável pela comunidade, e que pode ser auxiliado por outros padres (vigários paroquiais). O catequista nesse momento pode interrogar os catequizandos se eles sabem o nome do(s) padre(s) da paróquia. Poderá, se tiver, mostrar-lhes a foto de cada um. Uma visita poderá ser agendada na casa do padre para que os catequizandos criem laços com o sacerdote. As paróquias podem ser divididas em comunidades e setores. Poderá, se for oportuno, apresentar um pouco do histórico e da organização da paróquia, mostrando para ilustrar e melhor visualizar o mapa com o território paroquial e a divisão das comunidades e setores.</p></li> </ul> <p><strong>Observação:</strong> Dependendo da região, essas divisões podem ser diferentes, ou ainda receber outros nomes. Cada catequista adaptará a sua realidade o encontro de hoje. Se preferir, o esquema acima poderá ser invertido, começando das comunidades e setores, até chegar na Igreja Universal (católica).</p> <p><strong>Conclusão:</strong> No encontro de hoje fomos convidados a conhecer um pouco melhor a organização e a estrutura da nossa Igreja, e, como gesto concreto, o catequista poderá pedir aos catequizandos que no decorrer da semana façam uma lista de todas as pastorais, movimentos, associações presentes na paróquia, descrevendo qual o papel que cada uma desempenha na comunidade.</p> <p><strong>Oração final:</strong> Ao redor da Mesa da Palavra o catequista motiva os catequizandos a formularem orações e preces a Deus pedindo por toda comunidade paroquial. Depois o catequista conclui com o Pai-nosso e com a oração:</p> <p><em>Deus de infinita bondade, que congregastes vossos filhos em comunidades de amor, ajuda-nos a conhecer e a amar cada vez a tua Igreja. Por Cristo Nosso Senhor. Amém.</em></p> <p>No final da oração, o catequista impõe as mãos sobre a cabeça de cada catequizando e traça o sinal da cruz em sua fronte, dizendo:</p> <p><em>"...N... permanecei unido à videira, vai em paz, e que o Senhor te acompanhe!"</em></p> <h4>Regionais da CNBB</h4> <ul> <li><p>N1 – Norte 1 (norte do Amazonas e Roraima)</p></li> <li><p>N2 – Norte 2 (Amapá e Pará)</p></li> <li><p>NE1 – Nordeste 1 (Ceará)</p></li> <li><p>NE2 – Nordeste 2 (Alagoas, Paraíba, Pernambuco, Rio Grande do Norte e Fernando de Noronha)</p></li> <li><p>NE3 – Nordeste 3 (Bahia e Sergipe)</p></li> <li><p>NE4 – Nordeste 4 (Piauí)</p></li> <li><p>NE5 – Nordeste 5 (Maranhão)</p></li> <li><p>L1 – Leste 1 (Rio de Janeiro)</p></li> <li><p>L2 – Leste 2 (Espírito Santo e Minas Gerais)</p></li> <li><p>S1 – Sul 1 (São Paulo)</p></li> <li><p>S2 – Sul 2 (Paraná)</p></li> <li><p>S3 – Sul 3 (Rio Grande do Sul)</p></li> <li><p>S4 – Sul 4 (Santa Catarina)</p></li> <li><p>CO – Centro-Oeste (Distrito Federal, Goiás, Tocantins e parte do Mato Grosso)</p></li> <li><p>O1 – Oeste 1 (Mato Grosso do Sul)</p></li> <li><p>O2 – Oeste 2 (Mato Grosso)</p></li> <li><p>NO – Noroeste (Rondônia, Acre e sul do Amazonas)</p></li> </ul> <p>FONTE: disponível em: http://www.cnbb.org.br</p>', preparo_html='<p>Ambão com toalha da cor do Tempo Litúrgico, vela e flores, mapa territorial da diocese e foto do bispo diocesano, do pároco e vigários paroquiais, se houver.</p>', atualizado_em=now() where etapa_id=(select id from etapas where numero=2) and ordem=27; -- Uma só família
update encontros set conteudo_html='<p><strong>Palavra inicial:</strong> Neste encontro desenvolveremos junto aos catequizandos a concepção do que é ser santo. Deus nos convida a ter uma vida em santidade, e esse chamado é feito para todos. Procuramos conhecer melhor a vida das pessoas que se tornaram santas e tê-las como exemplo no nosso cotidiano.</p> <p><strong>Preparar o ambiente:</strong> Ambão com toalha da cor do Tempo Litúrgico, vela, flores e cestinha com várias imagens de santos (uma para cada catequizando) e uma imagem maior do santo padroeiro da paróquia ou da comunidade.</p> <p><strong>Acolhida:</strong> O catequista acolhe os catequizandos, saudando-os e conduzindo-os para dentro da sala: "...N... Cristo te chama à santidade, seja bem-vindo!" Quando já estiverem na sala, saúda a todos mais uma vez, desejando-lhes boas-vindas.</p> <p><strong>Recordação da vida:</strong> De pé, ao redor da Mesa da Partilha ou da Mesa da Palavra, após serem acolhidos, farão uma retrospectiva da semana, e o catequista poderá perguntar sobre o encontro anterior, pedindo para que partilhem o que cada um experienciou. Poderão destacar, ainda, os acontecimentos importantes que possam ter ocorrido na vida da comunidade.</p> <h4>Na Mesa da Palavra</h4> <p><strong>Oração inicial:</strong> O catequista inicia a oração invocando o Espírito Santo, rezando ou cantando. Poderá ser rezada, se oportuno, a Profissão de Fé.</p> <p>O catequizando (escalado como leitor do encontro) dirige-se até o ambão, de onde proclama o texto bíblico. Antes, porém, todos poderão aclamar o Evangelho.</p> <p><strong>Leitura do texto bíblico:</strong> <em>Mt 5,43-48</em>.</p> <p>Depois de um momento de silêncio o catequista lê o texto novamente bem devagar, destacando alguns pontos.</p> <p>"[...] sede perfeitos como o vosso Pai celeste é perfeito."</p> <h4>Na Mesa da Partilha</h4> <p>Todos se dirigem para a Mesa da Partilha.</p> <p>Reconstruir o texto bíblico com os catequizandos. Depois pedir para abrirem suas bíblias na passagem proclamada na Mesa da Palavra, e os convida a uma leitura silenciosa, observando algum detalhe não comentado na reconstrução do texto. Se houver algo, todos podem partilhar. Refletir junto aos catequizandos o texto bíblico, enfatizando que Deus nos convida a ser perfeitos. Esse convite é feito a todos. Várias pessoas que se tornaram santas foram pessoas como nós, porém aceitaram esse convite e tiveram suas vidas transformadas na doação. O catequista poderá questionar junto aos catequizandos o que faz com que uma pessoa seja santa (deixar que falem). O catequista poderá dar exemplos de pessoas que viveram na santidade, frisando que os santos não são só aqueles que foram elevados aos altares, mas todos nós somos convidados à santidade. Os santos não foram perfeitos, mas foram aqueles que reconheceram seus erros e limitações e se esforçaram para serem melhores a cada dia, se esforçaram para colocar em prática os mandamentos do Senhor.</p> <p>O catequista deverá pegar a imagem do santo padroeiro da sua paróquia ou comunidade (que estava no ambão). Apresentar aos catequizandos, perguntando se eles o conhecem, sabe sua história (deixar os catequizandos falarem).</p> <p>O catequista então conta a vida do santo e explica por que foi escolhido para ser padroeiro da sua paróquia ou comunidade (é importante que os catequizandos também tenham conhecimento da história da sua paróquia ou comunidade, se essa não foi apresentada no encontro passado). O catequista poderá escolher outro santo, que não seja o padroeiro da paróquia ou da comunidade, se achar oportuno.</p> <p>Após conversarem, deverá espalhar na Mesa da Partilha todas as imagens de santinho que trouxe. Pedir para que cada catequizando escolha uma que mais tenha se identificado (poderá ter imagens repetidas).</p> <p>Depois que cada catequizando escolheu, deverá ser proposto que cada catequizando durante a semana pesquise sobre a vida daquele santo e registre a sua história no Diário Catequético e Espiritual. Essa pesquisa pode ser feita através de pergunta aos pais, internet, pergunta ao padre, pesquisa em livros, entre outros.</p> <p>No próximo encontro, cada catequizando deverá trazer a imagem (foto) e expor para os demais colegas as informações que obteve sobre a vida daquele santo.</p> <p><strong>Conclusão:</strong> Cremos na comunhão dos santos, pois Cristo santifica a sua Igreja. Os santos são os que vivem ainda peregrinos aqui na terra, testemunhando o amor de Jesus Cristo e por Ele sofrendo muitas vezes, bem como todos os que já se encontram na glória de Deus, no céu, o qual unimo-nos pela fé na vida eterna.</p> <p>Se achar oportuno o catequista poderá falar-lhes sobre o purgatório, onde se encontram aqueles que morreram na amizade de Deus, mas, embora certos de sua salvação eterna, têm ainda necessidade de purificação para obter a santidade necessária e entrar definitivamente na alegria de Deus.</p> <p>O catequista, por fim, deverá incentivar a pesquisa sobre a vida dos santos. Dessa forma conheceremos mais profundamente a vida desses homens e mulheres que intercedem por nós.</p> <p><strong>Oração final:</strong> Ao redor da Mesa da Palavra, o catequista motiva os catequizandos a formularem preces e orações pedindo por todos os batizados, para que sejam fiéis ao chamado à santidade. Poderá encerrar com o Pai-nosso e com a oração:</p> <p>Senhor nosso Deus, que chamastes tantos homens e mulheres à santidade, pedimos humildemente que chame a cada um de nós e nos ajude a viver e a testemunhar teus mandamentos. Por Cristo Nosso Senhor. Amém.</p> <p>No final da oração, o catequista impõe as mãos sobre a cabeça de cada catequizando e traça o sinal da cruz em sua fronte, dizendo:</p> <p>"...N... buscai a santidade, vai em paz, e que o Senhor te acompanhe! Amém".</p> <h4>Material de apoio</h4> <p>- Aprofundar o tema nos parágrafos 946 a 962 do Catecismo da Igreja Católica (CIC).</p>', preparo_html='<p>Ambão com toalha da cor do Tempo Litúrgico, vela, flores e cestinha com várias imagens de santos (uma para cada catequizando) e uma imagem maior do santo padroeiro da paróquia ou da comunidade.</p>', atualizado_em=now() where etapa_id=(select id from etapas where numero=2) and ordem=28; -- Na comunhão dos santos
update encontros set conteudo_html='<p><strong>Palavra inicial:</strong> Neste encontro continuaremos a falar sobre a santidade que Deus pede a cada um de nós. Através da pesquisa feita durante a semana pelos nossos catequizandos, conheceremos mais profundamente a vida dessas pessoas que se tornaram santas, sendo veneradas nos altares das igrejas do mundo todo.</p> <p><strong>Preparar o ambiente:</strong> Ambão com toalha da cor do Tempo Litúrgico, vela e flores. Painel onde serão afixadas as fotos de todos os santos pesquisados pelos catequizandos (poderá ser feito com uma placa de isopor ou cartolina).</p> <p><strong>Acolhida:</strong> O catequista acolhe os catequizandos, saudando-os e conduzindo-os para dentro da sala: "...N... Cristo te chama à santidade, seja bem-vindo!"</p> <p><strong>Recordação da vida:</strong> Todos se colocam em pé ao redor da Mesa da Partilha ou da Mesa da Palavra onde farão uma retrospectiva da semana, destacando os acontecimentos importantes que possam ter ocorrido na vida da comunidade.</p> <h4>Na Mesa da Palavra</h4> <p><strong>Oração inicial:</strong> O catequista deverá motivar a oração inicial de maneira bem simples e que seja o mais espontânea possível. Poderá invocar o Espírito Santo com um canto ou com a oração "Vinde Espírito Santo, enchei..." Poderá ainda rezar a Profissão de Fé.</p> <p>O catequizando (escalado como leitor do encontro) dirige-se até o ambão, de onde proclama o texto bíblico.</p> <p><strong>Leitura do texto bíblico:</strong> <em>1Jo 2,3-6</em>.</p> <p>Depois de um momento de silêncio o catequista lê o texto novamente bem devagar, destacando alguns pontos.</p> <p>"[...] Dessa maneira sabemos que estamos nele. Quem permanece nele deve também viver como Jesus Cristo viveu."</p> <p>Todos se dirigem para a Mesa da Partilha.</p> <h4>Na Mesa da Partilha</h4> <p>Refletir junto aos catequizandos o texto bíblico, enfatizando que Jesus nos convida a sermos perfeitos, santos, como santo é o PAI. Que a santidade é uma busca constante em colocar em prática os mandamentos de Deus.</p> <p>Depois pedir aos catequizandos para abrirem suas bíblias na passagem proclamada na Mesa da Palavra, e os convida a uma leitura silenciosa, observando algum detalhe não comentado na reconstrução do texto. Se houver algo, todos podem partilhar.</p> <p>Relembrar com os catequizandos a história do santo padroeiro da paróquia ou comunidade.</p> <p>Perguntar aos catequizandos quem fez a pesquisa sobre a vida de um santo conforme foi solicitado no encontro anterior. Criar um clima de confiança e tranquilidade para que cada catequizando possa expor para a turma a sua pesquisa sem nervosismo.</p> <p>Nesse momento deverá ser pego o painel (bloco de isopor), e, à medida que cada catequizando for apresentar o seu santo, deverá pregar com alfinete ou com fita adesiva no isopor ou cartolina a imagem do santo que pesquisou. Após afixar a foto, o catequizando deverá contar tudo o que descobriu sobre a vida do santo e o que mais lhe chamou a atenção.</p> <p>O catequista deverá indagar aos demais catequizandos se eles querem acrescentar ou perguntar algo para o expositor. Também deverá complementar a história do santo, caso tenha ficado esquecido algum relato importante sobre a sua vida (fazer isso ao final de cada apresentação).</p> <p><strong>Conclusão:</strong> O catequista deverá colocar no ambão o painel junto com as imagens dos santos. Pedir para que os catequizandos olhem para imagem e vejam ali, retratadas, imagens de pessoas que tiveram uma vida de doação ao próximo, sendo obedientes à Palavra de Deus. Depois o catequista pode pedir para cada catequizando escolher o santo que mais lhe chamou atenção e anota o seu nome, para que, a partir deste encontro, o santo escolhido seja o seu santo de devoção, e, sempre nos momentos pessoais de oração, o catequizando possa pedir sua intercessão.</p> <p>No final, o catequista orienta os catequizandos a colarem ou desenharem a foto do santo que escolheram como modelo e intercessor no Diário Catequético e Espiritual.</p> <p><strong>Oração final:</strong> Na Santa Missa, durante a celebração o padre faz um pedido. Ele pede que nós sejamos uma oferenda perfeita ao Pai. Vamos repetir juntos essa parte da Liturgia Eucarística (o catequista reza e os catequizandos repetem):</p> <p>"Fazei de nós/ uma oferenda perfeita/ para alcançarmos a vida eterna/ com os vossos santos/ A virgem Maria mãe de Deus/ os vossos apóstolos e mártires/ e todos os santos/ que não cessam/ de interceder por nós/ na vossa presença".</p> <p>Logo após o catequista reza o Pai-nosso e conclui com a oração:</p> <p>Deus Pai bondoso, olhai pelos vossos filhos e filhas que aqui hoje se reúnem e aspiram à santidade. Fazei que, a exemplo de tantos homens e mulheres, possamos chegar um dia à vida eterna. Por Cristo Nosso Senhor. Amém.</p> <p>No final da oração, o catequista impõe as mãos sobre a cabeça de cada catequizando e traça o sinal da cruz em sua fronte, dizendo:</p> <p>"...N..., sede santo. Vai em paz, e que o Senhor te acompanhe! Amém".</p>', preparo_html='<p>Ambão com toalha da cor do Tempo Litúrgico, vela e flores. Painel onde serão afixadas as fotos de todos os santos pesquisados pelos catequizandos (poderá ser feito com uma placa de isopor ou cartolina).</p>', atualizado_em=now() where etapa_id=(select id from etapas where numero=2) and ordem=29; -- Modelos de santidade
update encontros set conteudo_html='<p><strong>Palavra inicial:</strong> Prezados catequistas, neste encontro buscaremos refletir com os catequizandos sobre o décimo artigo da Profissão de Fé. Cristo conferiu à Igreja o poder de perdoar os pecados.</p> <p><strong>Preparar o ambiente:</strong> Ambão com toalha da cor do Tempo Litúrgico, vela, flores e quadro com imagem do Pai misericordioso (<em>Lc 15,11-24</em>) e estola roxa, jarro com água e bacia, lembrando o batismo, veste branca e toalha para os catequizandos enxugarem as mãos.</p> <p><strong>Acolhida:</strong> O catequista acolhe os catequizandos, saudando-os e conduzindo-os para dentro da sala: "...N..., a Igreja te chama à reconciliação, seja bem-vindo!" Quando já estiverem na sala, saúda a todos mais uma vez, desejando-lhes boas-vindas.</p> <p><strong>Recordação da vida:</strong> De pé, ao redor da Mesa da Partilha ou da Mesa da Palavra, os catequizandos farão uma retrospectiva da semana, destacando os acontecimentos e fatos importantes que possam ter ocorrido na vida da comunidade.</p> <h4>Na Mesa da Palavra</h4> <p><strong>Oração inicial:</strong> Em clima de oração e recolhimento o catequista inicia a oração invocando o Espírito Santo, rezando ou cantando. Poderá ser rezada, se oportuno, a Profissão de Fé, e aclamar o Evangelho com um canto.</p> <p>O catequizando (escalado como leitor do encontro) dirige-se até o ambão, de onde proclama o texto bíblico. Antes, porém, todos podem aclamar o Evangelho com um canto.</p> <p><strong>Leitura do texto bíblico:</strong> <em>Lc 24,45-48</em>.</p> <p>Depois de um momento de silêncio o catequista lê o texto novamente bem devagar, destacando alguns pontos.</p> <p>"[...] em seu nome seria pregada a todas as nações a conversão para o perdão dos pecados..."</p> <p>Todos se dirigem para a Mesa da Partilha.</p> <h4>Na Mesa da Partilha</h4> <p>Reconstruir o texto bíblico. Depois pedir aos catequizandos para abrirem suas bíblias na passagem proclamada na Mesa da Palavra, e os convida a uma leitura silenciosa, observando algum detalhe não comentado na reconstrução do texto. Se houver algo, todos podem partilhar. Refletir com os catequizandos o texto bíblico, enfatizando que Jesus morreu na cruz por amor à humanidade, para salvar todo homem e mulher da morte do pecado. Por sua morte todos fomos lavados em seu sangue. Ele, não tendo pecado, assumiu os nossos pecados.</p> <p>O próprio Cristo deixou, antes de subir junto ao Pai, a missão e o poder à Igreja de perdoar os pecados.</p> <p>Pedir aos catequizandos para que abram suas bíblias e procurem a passagem de <em>Jo 20,22-23</em>. Pedir para que um dos catequizandos a proclame.</p> <p>Depois refletir com os catequizandos dizendo que foi transmitindo o Espírito Santo aos apóstolos que Cristo ressuscitado lhes conferiu seu próprio poder de perdoar os pecados (CIC 976). Portanto, a Igreja tem essa missão e poder de perdoar todos os pecados daqueles que com coração sincero e arrependido pedirem o perdão. Não há pecado algum que a Santa Igreja não possa perdoar.</p> <p>O primeiro e principal sacramento para a remissão dos pecados é o Batismo. Nele somos lavados e purificados (o catequista pode mostrar o jarro com água e a veste branca, fazendo menção a esse sacramento). Para os pecados cometidos depois do Batismo, Cristo instituiu o Sacramento da Reconciliação ou Penitência, por meio do qual o batizado se reconcilia com Deus e com a Igreja (podendo mostrar a estola roxa, fazendo menção a esse sacramento).</p> <p>Os padres e os sacramentos são meros instrumentos dos quais Cristo, único autor e dispensador de nossa salvação, se apraz em se servir para pagar nossas faltas e dar-nos a graça da justificação (CIC 987).</p> <p>Após expor o conteúdo, o catequista poderá propor aos catequizandos um momento de silêncio para que possam refletir sobre as suas faltas, naquilo que cada um poderia melhorar. No amor ao próximo, no respeito e obediência aos pais etc. Poderá ser colocada uma música instrumental para contribuir à reflexão.</p> <p>Depois de alguns minutos o catequista convida cada catequizando a se aproximar da bacia com água onde um catequizando lavará a mão do outro, simbolizando que, lavados pelo batismo, somos responsáveis por ajudar nossos irmãos e irmãs a viverem retamente. Enquanto isso poderá se ter um canto.</p> <p><strong>Conclusão:</strong> O catequista reforça aos catequizandos a importância dos sacramentos, principalmente o Sacramento da Penitência, dizendo que é um momento por excelência para se reconciliar com Deus, pois, quando pecamos, dele nos distanciamos. Além disso, poderá ir preparando-os, dizendo que o ano que vem, na terceira etapa, eles serão convidados a fazer a experiência da confissão individual com o padre, onde o próprio Jesus estará de braços abertos a nos acolher.</p> <p><strong>Oração final:</strong> Ao redor da Mesa da Palavra, o catequista motiva os catequizandos a formularem preces e pedidos de perdão. Poderá encerrar com o Pai-nosso e com a oração:</p> <p>"Senhor nosso Deus, que olha com amor e com misericórdia para o ser humano. Tenha compaixão de cada um de nós e que, ao nos aproximarmos dos sacramentos da tua Igreja, sejamos acolhidos no amor. Por Cristo Nosso Senhor. Amém."</p> <p>No final da oração, o catequista impõe as mãos sobre a cabeça de cada catequizando e traça o sinal da cruz em sua fronte, dizendo:</p> <p>"...N... vai em paz, e que o Senhor te acompanhe! Amém".</p> <h4>MATERIAL DE APOIO</h4> <ul> <li><p>Aprofundar o tema nos parágrafos 976 a 987 do Catecismo da Igreja Católica (CIC).</p></li> <li><p>No Símbolo niceno-constantinopolitano: "[...] Professo um só batismo para a remissão dos pecados..."</p></li> </ul>', preparo_html='<p>Ambão com toalha da cor do Tempo Litúrgico, vela, flores e quadro com imagem do Pai misericordioso ( Lc 15,11-24 ) e estola roxa, jarro com água e bacia, lembrando o batismo, veste branca e toalha para os catequizandos enxugarem as mãos.</p>', atualizado_em=now() where etapa_id=(select id from etapas where numero=2) and ordem=30; -- Na remissão dos pecados
update encontros set conteudo_html='<p><strong>Palavra inicial:</strong> Amado catequista, no encontro de hoje queremos refletir sobre os dois últimos artigos da Profissão de Fé. Acreditar na ressurreição da carne e na vida eterna.</p> <p><strong>Preparar o ambiente:</strong> Ambão com toalha da cor do Tempo Litúrgico, vela, flores. Fotos ou imagens de uma lagarta, casulo e de uma borboleta.</p> <p><strong>Acolhida:</strong> À medida que os catequizandos vão chegando, o catequista os acolhe, saudando-os com a frase: "...N..., nós cremos na vida eterna, seja bem-vindo!", e convida-os a entrarem para o local do encontro.</p> <p><strong>Recordação da vida:</strong> Ao redor da Mesa da Partilha ou da Mesa da Palavra o catequista motiva os catequizandos a fazer um momento de recordação da vida, onde lembrarão fatos e acontecimentos que marcaram a vida de cada um, de suas famílias, comunidade e da sociedade.</p> <h4>Na Mesa da Palavra</h4> <p><strong>Oração inicial:</strong> Após o momento de recordação da vida, o catequista inicia um momento de oração pedindo o Espírito Santo sobre todos os catequizandos e sobre toda a Igreja. Poderá rezar o Credo.</p> <p>Ainda em clima de oração, o catequizando (escalado como leitor do encontro) dirige-se até o ambão, de onde proclama o texto bíblico.</p> <p><strong>Leitura do texto bíblico:</strong> Rm 8,9-11.</p> <p>Depois de um momento de silêncio o catequista lê o texto novamente bem devagar, destacando alguns pontos.</p> <p>"[...] se o Espírito daquele que ressuscitou Jesus dos mortos habita em vós, quem ressuscitou Jesus Cristo dos mortos também dará a vida a vossos corpos mortais pelo seu Espírito que habita em vós."</p> <p>Todos se dirigem para a Mesa da Partilha.</p> <h4>Na Mesa da Partilha</h4> <p>O catequista incentiva os catequizandos a reconstruírem o texto bíblico. Depois pedir aos catequizandos para abrirem suas bíblias na passagem proclamada na Mesa da Palavra, e os convida a uma leitura silenciosa, observando algum detalhe não comentado na reconstrução do texto. Se houver algo, todos podem partilhar. Logo após conta a história "Um até breve, Padre Pedro".</p> <p>Um até breve, Padre Pedro</p> <p>Muitos anos haviam se passado desde que os gêmeos Otávio e Leandro, e Isabel, haviam viajado no tempo indo parar na época de Jesus. E a mesma viagem haviam feito o Padre Pedro, Fernando e Amanda. Vocês se lembram que Fernando era aquele menino cego que, ao crescer, se casou e teve dois filhos, os gêmeos? Ah e claro, que era músico e que integrava um grupo que fazia a animação das missas dominicais à noite? E também de Amanda, mãe de Isabel, e do Padre Pedro, que no primeiro ano de catequese o chamávamos de Pedrinho, não é mesmo?</p> <p>Então, os três já estavam bem velhinhos. Os gêmeos estavam casados, tinham filhos, e Isabel havia se tornado freira. Depois de uns sete anos sem se encontrarem eles estavam juntos, só que por um motivo não muito bom. Eles estavam no velório do Padre Pedro.</p> <p>Apesar de ser um momento de muita saudade e tristeza, eles sabiam que o padre estava bem, aliás, bem melhor do que ali. Ele também tinha a certeza de que não era o fim da vida do padre, mas o recomeço de uma nova vida.</p> <p>E Otávio explicava para seus filhos, Augusto e Miriam, que assim como Jesus morreu e ressuscitou, nós todos também morreremos e ressuscitaremos com Ele por meio do Espírito Santo.</p> <p>- Ah papai, mas é ruim ficar com saudade das pessoas que morrem - disse Miriam.</p> <p>- Sentir saudades não é legal mesmo, mas é assim que acontece e todos vamos nos reencontrar com aqueles que já morreram; então, esse sentimento chato não vai durar para sempre.</p> <p>- Ah que bom! - respondeu Miriam, que foi brincar com o irmão Augusto e outras crianças.</p> <p>Antes do enterro, Isabel, que agora era a irmã Isabel, rezou o terço, e Fernando cantou e tocou a seguinte música:</p> <p>- Se as águas, do mar da vida, quiserem te afogar... Segura na mão de Deus e vai! Segura na mão de Deus, segura na mão de Deus. Pois ela, ela te sustentará. Não temas, segue adiante e não olhes para trás. Segura na mão de Deus e vai!</p> <p>E na hora do enterro, no final da tarde, fez-se um belíssimo pôr do sol. Borboletas enfeitaram o céu naquele momento que não era de despedida, mas um até breve.</p> <p>No final da história perguntar aos catequizandos o que eles sabem sobre o que acontece com a lagarta depois de um tempo (mostrar a foto da lagarta). Deixar os catequizandos falarem.</p> <p>Depois mostra-lhes a foto do casulo e da borboleta, dizendo que o que a lagarta nela experimenta é a morte, quando ela se transforma em casulo e dele sai uma linda borboleta. Entretanto, a sua morte não é o fim, mas transformação, através da qual aparece um ser qualitativamente novo, a borboleta (Renold J. Blank, 2000). Ou seja, nós somos essa lagartinha que caminha neste mundo, feia muitas vezes por causa de nossos pecados, mas após um tempo precisamos partir, morremos, fazemos nossa páscoa (passagem para junto de Deus) e nos transformamos em lindas borboletas, coloridas, sem pecado, a estar eternamente junto de Deus. O casulo que fica é o nosso corpo corruptível, sinal da nossa peregrinação terrestre, sinal da nossa passagem para a vida eterna. No céu seremos únicos e viveremos junto de Deus, num lugar sem dor, sem violência, sem tristeza. Só Deus nos bastará.</p> <p>E no final dos tempos, após o juízo final, quando Deus inaugurar os “novos céus” e a “nova terra” (2Pd 3,13), onde Deus será tudo em todos, os nossos corpos mortais readquirirão a vida. O nosso estado definitivo não será apenas a alma espiritual separada do corpo. Como Cristo ressurgiu verdadeiramente dos mortos e vive para sempre, assim também ressuscitará a todos no último dia, com um corpo incorruptível.</p> <p>O catequista, se oportuno, poderá deixar claro que a fé da Igreja é na ressurreição e NÃO na encarnação.</p> <p><strong>Conclusão:</strong> O catequista poderá perguntar aos catequizandos sobre o que eles entenderam sobre o que é a vida eterna. Depois encerrar dizendo que nossa vida neste mundo é passageira, somos apenas peregrinos e que nosso lugar é estar junto de Deus. Como gesto concreto, no decorrer da semana rezar a Deus, pedindo que Ele nos perdoe de todos os pecados e um dia nos conduza junto dele. Poderá ser pedido, ainda, que os catequizandos lembrem e rezem durante a semana, para membros de sua família e amigos que já faleceram e já estão junto de Deus.</p> <p><strong>Oração final:</strong> O catequista convida a todos a se colocarem ao redor da Mesa da Palavra onde estimula os catequizandos a formularem preces e orações principalmente por aquelas pessoas que não acreditam em Deus, na salvação de Jesus e para que Deus tenha misericórdia e compaixão de todo o mundo. Conclui com o Pai-nosso e com a oração:</p> <p>"Deus de Misericórdia, que enviaste seu Filho ao mundo para a remissão dos pecados, olhe com ternura a cada um de nós, e nos conduza um dia à morada celeste, onde viveremos eternamente gozando de sua Luz. Por Cristo Nosso Senhor. Amém."</p> <p>No final da oração, o catequista impõe as mãos sobre a cabeça de cada catequizando e traça o sinal da cruz em sua fronte, dizendo:</p> <p>"...N... você é um cidadão do céu, vai em paz, e que o Senhor te acompanhe!"</p> <h4>MATERIAL DE APOIO</h4> <ul> <li><p>Aprofundar o tema nos parágrafos 988 a 1065 do Catecismo da Igreja Católica (CIC).</p></li> <li><p>No Símbolo niceno-constantinopolitano: "[...] E espero a ressurreição dos mortos e a vida do mundo que há de vir. Amém".</p></li> </ul> <p>Poderá ser pedido, ainda, que os catequizandos lembrem e rezem durante a semana, para membros de sua família e amigos que já faleceram e já estão junto de Deus.</p> <p><strong>Oração final:</strong> O catequista convida a todos a se colocarem ao redor da Mesa da Palavra onde estimula os catequizandos a formularem preces e orações principalmente por aquelas pessoas que não acreditam em Deus, na salvação de Jesus e para que Deus tenha misericórdia e compaixão de todo o mundo. Conclui com o Pai-nosso e com a oração:</p> <p>"Deus de Misericórdia, que enviaste seu Filho ao mundo para a remissão dos pecados, olhe com ternura a cada um de nós, e nos conduza um dia à morada celeste, onde viveremos eternamente gozando de sua Luz. Por Cristo Nosso Senhor. Amém."</p> <p>No final da oração, o catequista impõe as mãos sobre a cabeça de cada catequizando e traça o sinal da cruz em sua fronte, dizendo:</p> <p>"...N... você é um cidadão do céu, vai em paz, e que o Senhor te acompanhe!"</p> <h4>MATERIAL DE APOIO</h4> <ul> <li><p>Aprofundar o tema nos parágrafos 988 a 1065 do Catecismo da Igreja Católica (CIC).</p></li> <li><p>No Símbolo niceno-constantinopolitano: "[...] E espero a ressurreição dos mortos e a vida do mundo que há de vir. Amém".</p></li> </ul>', preparo_html='<p>Ambão com toalha da cor do Tempo Litúrgico, vela, flores. Fotos ou imagens de uma lagarta, casulo e de uma borboleta.</p>', atualizado_em=now() where etapa_id=(select id from etapas where numero=2) and ordem=31; -- Creio “na ressurreição da carne, na vida eterna”
commit;
